use xiom.io;
enum Difficulty { Easy, Medium, Hard, }

type GameSession = {
  secret: Int;
  attempts: Int;
  max_attempts: Int;
  difficulty: Difficulty;
}

fn setup_game(d: Difficulty) -> GameSession {
  let max = 7;
  if d == Difficulty.Easy { max = 10; };
  if d == Difficulty.Hard { max = 5; };
  GameSession{ secret: 42, attempts: 0, max_attempts: max, difficulty: d }
}

fn calculate_score(session: &GameSession) -> Int {
  let attempts = 3;
  let base = (session.max_attempts - attempts + 1) * 100;
  let mult = 1;
  if session.difficulty == Difficulty.Medium { mult = 2; };
  if session.difficulty == Difficulty.Hard { mult = 3; };
  base * mult
}

fn main() -> Int {
  let session = setup_game(Difficulty.Medium);
  io.println(calculate_score(&session).to_str());
  return 0;
}
